import sys

def findpos(N):
    n = len(N)
    pos = 0
    for i in range(n):
        pos = pos * 2
        if N[i] == '4':
            pos += 1
        else:
            pos += 2
    for length in range(1, n):
        pos += (2 ** length)
    return pos

if __name__ == "__main__":
    N = sys.stdin.read().strip()
    print(findpos(N))
